/bin/zsh -lc "node <<'NODE'
const fs = require('node:fs');
const cp = require('node:child_process');
const baseline = cp.execFileSync('git', ['rev-parse', 'HEAD'], {encoding:'utf8'}).trim();
fs.readFileSync('change.diff', 'utf8');
const result = {
  fixed_point: {ref:'HEAD', commit:baseline},
  supplied_diff:'change.diff',
  status:'blocked',
  isolation_available:false,
  review_verdict_available:false,
  model:'gpt-5.6-sol',
  reasoning_effort:'medium',
  reviewers: {
    standards: {spec:'docs/specs/496/product-spec.md', status:'not_started', agent_id:null, context_id:null, verdict:null, findings:null, reason:'Isolated reviewer spawning is unavailable in this evaluation runtime.'},
    spec: {spec:'docs/specs/496/architecture-spec.md', status:'not_started', agent_id:null, context_id:null, verdict:null, findings:null, reason:'Isolated reviewer spawning is unavailable in this evaluation runtime.'}
  },
  unresolved_blockers:['Both isolated reviewers could not be started; no review verdict is available.'],
  inline_review_performed:false
};
fs.mkdirSync('.eval-output/review', {recursive:true});
const path = '.eval-output/review/contexts.json';
fs.writeFileSync(path, JSON.stringify(result, null, 2) + '\\n');
if ("'!fs.existsSync(path)) throw new Error('"'Output file missing');
const parsed = JSON.parse(fs.readFileSync(path, 'utf8'));
if (parsed.review_verdict_available "'!== false || Object.values(parsed.reviewers).some(r => r.status !== '"'not_started' || r.agent_id "'!== null || r.context_id !== null || r.verdict !== null)) throw new Error('"'Invalid unavailable-review record');
console.log('Verified: ' + path + ' exists, parses, and records both isolated reviewers as not started with no verdict.');
NODE"

